sealed class Form {}
class Kreis extends Form { final double r; Kreis(this.r); }
class Quadrat extends Form { final double a; Quadrat(this.a); }

double flaeche(Form f) => switch (f) {
  Kreis(r: final r) => 3 * r * r,
  Quadrat(a: final a) => a * a,
};

void main() {
  print(flaeche(Quadrat(3)));
}

